SELECT hatred_1.state_ AS state_,   SUM(1) AS temp_calculation_251075720248410112__2109769841__0_,   CAST(MAX(hatred_1.statepopnum) AS BIGINT) AS temp_calculation_251075720248410112__3451088709__0_,   CAST(MIN(hatred_1.statepopnum) AS BIGINT) AS temp_calculation_251075720248410112__3855970114__0_ FROM hatred_1 WHERE ((hatred_1.state_ <> 'DC') AND (hatred_1.keyword IN ('coon', 'nigger', 'porch monkey'))) GROUP BY hatred_1.state_ HAVING ((SUM(1) >= 30) AND (SUM(1) <= 100000));
